## Detailed Design & Consumer Configuration

```yaml
# application-kafka.yml
spring:
  kafka:
    consumer:
      enable-auto-commit: false
      max-poll-records: 50
      max-poll-interval-ms: 300000
      session-timeout-ms: 45000
      heartbeat-interval-ms: 3000
      properties:
        partition.assignment.strategy: org.apache.kafka.clients.consumer.CooperativeStickyAssignor
        group.instance.id: ${POD_NAME}
```

```java
// Poll loop excerpt with pause/resume backpressure
while (running) {
    ConsumerRecords<String, byte[]> records = consumer.poll(Duration.ofMillis(200));
    for (TopicPartition tp : records.partitions()) {
        partitionQueues.get(tp).addAll(records.records(tp));
        if (partitionQueues.get(tp).size() >= HIGH_WATERMARK) {
            consumer.pause(Collections.singleton(tp));
        }
    }
    Map<TopicPartition, OffsetAndMetadata> ready = drainCompletedOffsets();
    if (!ready.isEmpty()) consumer.commitSync(ready);
    resumeDrainedPartitions(consumer);
}
